// validateSignup —— 注册表单校验（毕业项目参考实现）
function isValidDateString(s) {
  if (typeof s !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
  var y = parseInt(s.slice(0, 4), 10);
  var m = parseInt(s.slice(5, 7), 10);
  var d = parseInt(s.slice(8, 10), 10);
  if (m < 1 || m > 12 || d < 1 || d > 31) return false;
  var dt = new Date(Date.UTC(y, m - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d;
}

function validateSignup(payload) {
  var p = payload || {};
  var errors = {};

  var name = typeof p.name === 'string' ? p.name.trim() : '';
  if (name.length < 2 || name.length > 40) errors.name = 'name_invalid';

  var email = typeof p.email === 'string' ? p.email.trim() : '';
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.email = 'email_invalid';

  var password = typeof p.password === 'string' ? p.password : '';
  var strong = password.length >= 8 &&
    /[a-z]/.test(password) && /[A-Z]/.test(password) &&
    /[0-9]/.test(password) && /[!@#$%^&*]/.test(password);
  if (!strong) errors.password = 'password_weak';

  var birthdate = p.birthdate;
  if (!isValidDateString(birthdate)) {
    errors.birthdate = 'birthdate_invalid';
  } else {
    var born = Date.UTC(+birthdate.slice(0, 4), +birthdate.slice(5, 7) - 1, +birthdate.slice(8, 10));
    var today = Date.UTC(2026, 10, 10);
    var cutoff = Date.UTC(2013, 10, 10);
    if (born > today) errors.birthdate = 'birthdate_future';
    else if (born > cutoff) errors.birthdate = 'birthdate_too_young';
  }

  return { ok: Object.keys(errors).length === 0, errors: errors };
}
